INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 4104, 'ruRU', 'Если во время поиска ископаемых в Оскверненном лесу у тебя будет с собой Маяк Кенария, ты сможешь найти порченый купорос, проникающий в жилы металлов. Я знаю, как очищать этот купорос и превращать его в реактив, который идет на изготовление кенарийского бальзама исцеления растений. Затем этим бальзамом можно исцелять пораженные растения.$B$BЕсли ты принесешь мне порченого купороса, я дам тебе уже готового кенарийского бальзама исцеления растений.' FROM `quest_request_items` WHERE `ID`=4104 AND MD5(`CompletionText`)='98ba1b7e9ca5603e6559d934fd7690f6' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=4104 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 4105, 'ruRU', 'Маяк Кенария позволяет опрытному травнику замечать коварный зародыш Скверны – мерзостный результат поразившей Оскверненный лес порчи. В результате долгих моих трудов здесь мне удалось научиться преврашать зародыш Скверны в очищающее вещество... которое мы используем для приготовления так называемого кенарийского бальзама исцеления растений.$B$BВо время сбора растений в Оскверненном лесу ты сможешь замечать зародыш Скверны, пока на тебе лежит заклятие Маяк Кенария. За то, что ты мне принесешь, я дам тебе уже готового кенарийского бальзама.' FROM `quest_request_items` WHERE `ID`=4105 AND MD5(`CompletionText`)='733589ff2d65254052ed569e9ccfcd6d' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=4105 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 4107, 'ruRU', 'Сила магического предмета соответствует силе эссенций, получающихся в результате его распыления. Мной изобретен способ переработки сырой субстанции, используемой зачаровывателями, в реактив, пригодный для создания кенарийского бальзама исцеления растений. Для этого тебе не нужен Маяк Кенария. Подойдет любой предмет, с которого сняты чары, и который выделяет простую субстанцию Пустоты.$B$BМне нужна всего одна порция простой субстанции Пустоты, а за это я тебе дам кенарийского бальзама исцеления. Эта субстанция чрезвычайно сильна – даже малого количества хватит надолго!' FROM `quest_request_items` WHERE `ID`=4107 AND MD5(`CompletionText`)='0197e71380744a7c89745a5ad760ffa7' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=4107 AND x.`locale`='ruRU');
