INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 4110, 'ruRU', 'Маяк Кенария позволяет опрытному травнику замечать коварный зародыш Скверны – мерзостный результат поразившей Оскверненный лес порчи. В результате долгих моих трудов здесь мне удалось научиться преврашать зародыш Скверны в очищающее вещество... которое мы используем для приготовления так называемого кенарийского бальзама исцеления растений.$B$BВо время сбора растений в Оскверненном лесу ты сможешь замечать зародыш Скверны, пока на тебе лежит заклятие Маяк Кенария. За то, что ты мне принесешь, я дам тебе уже готового кенарийского бальзама.' FROM `quest_request_items` WHERE `ID`=4110 AND MD5(`CompletionText`)='733589ff2d65254052ed569e9ccfcd6d' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=4110 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 4111, 'ruRU', 'Маяк Кенария позволяет опытному специалисту по снятию шкур находить куски пораженных порчей шкур среди добытого в Оскверненном лесу добра. Я перерабатываю эти вроде бы бесполезные обрывки в густую пасту, которая ускоряет действие кенарийского бальзама исцеления растений. Когда ты будешь свежевать туши убитых в Оскверненном лесу животных, позаботься, чтобы на тебе лежало заклятие Маяка Кенария!$B$BКогда соберешь порченые клочки, принеси их мне, и я дам тебе немного готового кенарийского бальзама исцеления растений.' FROM `quest_request_items` WHERE `ID`=4111 AND MD5(`CompletionText`)='33c97db3f0a8282eaf0b6f5bd5978ca8' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=4111 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 4112, 'ruRU', 'Сила магического предмета соответствует силе эссенций, получающихся в результате его распыления. Мной изобретен способ переработки сырой субстанции, используемой зачаровывателями, в реактив, пригодный для создания кенарийского бальзама исцеления растений. Для этого тебе не нужен Маяк Кенария. Подойдет любой предмет, с которого сняты чары, и который выделяет простую субстанцию Пустоты.$B$BМне нужна всего одна порция простой субстанции Пустоты, а за это я тебе дам кенарийского бальзама исцеления. Эта субстанция чрезвычайно сильна – даже малого количества хватит надолго!' FROM `quest_request_items` WHERE `ID`=4112 AND MD5(`CompletionText`)='0197e71380744a7c89745a5ad760ffa7' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=4112 AND x.`locale`='ruRU');
