INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 4802, 'ruRU', 'В Зимних Ключах тебе придется сражаться со свихнувшимися существами – фурболгами племени Зимней Спячки. По воле своего вождя они обрели невероятную силу. Если и ты хочешь получить силу этого племени, принеси мне э\'ко, что найдешь у них.$B$BИ не забудь, что сокровище Мау\'ари с собой нужно носить, если хочешь камень э\'ко добыть.' FROM `quest_request_items` WHERE `ID`=4802 AND MD5(`CompletionText`)='cf3eddb6ead9ab484479ee0887113aa4' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=4802 AND x.`locale`='ruRU');
