INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 5059, 'ruRU', 'Дверь в служебное помещение потрескалась, будто кто-то долго и упорно пытался ее выломать. В настоящий момент она заперта снаружи.$B$BПодергав за ручку, вы слышите изнутри утробные стоны! Что бы ни скрывалось внутри, оно кажется совсем недружелюбным.' FROM `quest_request_items` WHERE `ID`=5059 AND MD5(`CompletionText`)='c72da12e5d9890c1da67287a2e3d0fd9' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=5059 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 5060, 'ruRU', 'Перед вами массивный шкаф, надежно запертый на врезной замок. Дверцы шкафа сильно исцарапаны. Судя по всему, его не раз пытались взломать, чтобы посмотреть, что внутри.$B$BПохоже, без ключа этот шкаф не открыть.' FROM `quest_request_items` WHERE `ID`=5060 AND MD5(`CompletionText`)='5bc88ef76d270dc77f0fc893f730994d' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=5060 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 5121, 'ruRU', 'Может, ты узнаешь больше в Деревне Зимней Спячки, $N.' FROM `quest_request_items` WHERE `ID`=5121 AND MD5(`CompletionText`)='83b4c95567534bd35ca2661c70cbd926' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=5121 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 5155, 'ruRU', 'Как продвигается твой бой, $N? Я знаю, что пролитие крови в качестве доказательства чести может вызывать у некоторых отвращение, но ты должен понять, что это служит двум целям: вы облегчите мою задачу, нанеся ущерб их количеству, и мы завоюем уважение друг к другу, которое только сделает нас сильнее в будущем.$B$BНадеюсь, ты понимаешь.' FROM `quest_request_items` WHERE `ID`=5155 AND MD5(`CompletionText`)='93456cd2ac42023f83c47e1cf150643b' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=5155 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 5156, 'ruRU', 'Надеюсь, твои поиски пройдут успешно, $N. Я еще не начал двигаться так далеко на север, но признаю, мысль о том, что по пути я могу встретить инферналов, меня немного пугает. Хоть у них и нет разума, но всё же они довольно устрашающие.' FROM `quest_request_items` WHERE `ID`=5156 AND MD5(`CompletionText`)='5f33482c53bc6103ad26c040d0a0ecfc' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=5156 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 5165, 'ruRU', 'Жаровни должны быть потушены, если мы хотим иметь хоть какую-то надежду подготовиться к гораздо более серьезной битве. Идти в логово дракона без всякого ведома - глупая затея. И это намного хуже дракона. Совет Теней несет полную ответственность за множество преступлений и злодеяний. Придется действовать быстро, чтобы их остановить.' FROM `quest_request_items` WHERE `ID`=5165 AND MD5(`CompletionText`)='25860d7a7798230c5799faaa796312bf' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=5165 AND x.`locale`='ruRU');
