INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 5402, 'ruRU', 'Камень приспешника Плети  – знак различия Плети. Иногда их можно найти у нежити, у более слабых бойцов, хотя слово слабый – относительное понятие. Не стоит недооценивать Плеть.$B$BОт имени Серебряного Рассвета я готов вручить тебе по знаку доблести за каждые двадцать камней, причем с радостью – чем больше ты убьешь приспешников Плети, тем лучше.' FROM `quest_request_items` WHERE `ID`=5402 AND MD5(`CompletionText`)='3ef318b18661c8cdf4dc3a264156aa2f' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=5402 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 5403, 'ruRU', 'Камень захватчика Плети – знак различия элитных войск Плети. Порой их можно найти у сильных бойцов в Чумных землях. Убить таких бойцов – настоящий подвиг, который должно совершать во имя борьбы со злом.$B$BСеребряный Рассвет вручает знак доблести в обмен на десять таких камней. Принеси их мне, и непременно получишь достойную награду.' FROM `quest_request_items` WHERE `ID`=5403 AND MD5(`CompletionText`)='47d8e57784dc7713edace0708891cddd' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=5403 AND x.`locale`='ruRU');
