INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 5883, 'ruRU', 'Если во время поиска ископаемых в Оскверненном лесу у тебя будет с собой Маяк Кенария, ты сможешь найти порченый купорос, проникающий в жилы металлов. Я знаю, как очищать этот купорос и превращать его в реактив, который идет на изготовление кенарийского бальзама исцеления растений. Затем этим бальзамом можно исцелять пораженные растения.$B$BЕсли ты принесешь мне порченого купороса, я дам тебе уже готового кенарийского бальзама исцеления растений.' FROM `quest_request_items` WHERE `ID`=5883 AND MD5(`CompletionText`)='98ba1b7e9ca5603e6559d934fd7690f6' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=5883 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 5886, 'ruRU', 'Сила магического предмета соответствует силе эссенций, получающихся в результате его распыления. Мной изобретен способ переработки сырой субстанции, используемой зачаровывателями, в реактив, пригодный для создания кенарийского бальзама исцеления растений. Для этого тебе не нужен Маяк Кенария. Подойдет любой предмет, с которого сняты чары, и который выделяет простую субстанцию Пустоты.$B$BМне нужна всего одна порция простой субстанции Пустоты, а за это я тебе дам кенарийского бальзама исцеления. Эта субстанция чрезвычайно сильна – даже малого количества хватит надолго!' FROM `quest_request_items` WHERE `ID`=5886 AND MD5(`CompletionText`)='7def2d14045da7cfab62dc1ddfda7332' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=5886 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 5887, 'ruRU', 'Обладание Маяком Кенария позволяет увидеть оскверненные осколки души затронутых порчей животных, убитых ради вящего блага. Я измельчаю эти осколки и делаю из них реактив, который идет на изготовление кенарийского бальзама исцеления растений. Мы используем это средство для исцеления пораженных порчей растений.$B$BЗа эти осколки я дам тебе немного уже готового кенарийского бальзама исцеления растений.' FROM `quest_request_items` WHERE `ID`=5887 AND MD5(`CompletionText`)='4cfcb8c214d9c7c613404a5c4eb3ff8f' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=5887 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 6143, 'ruRU', 'Ты нашел Скипетр Света? Он у тебя?' FROM `quest_request_items` WHERE `ID`=6143 AND MD5(`CompletionText`)='1a2a5c0ac969d13337db20b30779d942' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=6143 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 6544, 'ruRU', 'Надеюсь, ты с грузом? У меня будут большие неприятности, если я не доставлю все как можно скорее!' FROM `quest_request_items` WHERE `ID`=6544 AND MD5(`CompletionText`)='03d79ca5959828d8179bd9c33b3e215c' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=6544 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 6581, 'ruRU', 'Прямо из Кабестана, свежие лезвия для пил Песни Войны! Да, они у меня с собой.$B$BНо чем вы мне заплатите? Вы же не можете забрать их просто так! Мое время дорого стоит!$B$BЧестно говоря, мне нужно доброе ружье для моих поездок. Девушке ведь надо уметь защитить себя, вы ведь понимаете? Есть одно ружье, которое мне по нраву, и я уверена, что инженер без проблем такое сделает.$B$BИ если вы принесете мне хороший мушкетон, я отдам вам партию лезвий. Идет?' FROM `quest_request_items` WHERE `ID`=6581 AND MD5(`CompletionText`)='1b78abdcdebf2bf58bbbabb19f60e5bf' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=6581 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 7429, 'ruRU', 'Эта вещь называется "ключ от оков Гордока" – по крайней мере, так называют его эти "остроумцы". Думаю, такой ключ может быть у любого из огров, но у кого именно – сказать не возьмусь. Есть вероятность, что такие ключи имеются у стражников…$b$bНо о чем я говорю? Он у вас есть, да? Он при вас?!' FROM `quest_request_items` WHERE `ID`=7429 AND MD5(`CompletionText`)='17e9d56fd2bdc271dc96912096df63bd' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=7429 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 7490, 'ruRU', 'Когда Тралл видит громадную голову Ониксии, его всегдашнее самообладание на миг ему изменяет. Тралл уже готов схватиться за свой легендарный Молот Рока!' FROM `quest_request_items` WHERE `ID`=7490 AND MD5(`CompletionText`)='d8746fbab64f73d0e00871890436977d' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=7490 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 7802, 'ruRU', 'Мы сейчас собираем пожертвования в виде шерстяной ткани. За щедрый дар вы получите признательность Стальгорна. Наши запасы таковы, что нам нужно от вас всего лишь шестьдесят отрезов. Мы могли бы купить их и на стороне, чтобы продолжить работу.$B$BНо если вы имеете шестьдесят отрезов шерстяной ткани и готовы пожертвовать их в дар, я с готовностью приму их у вас прямо сейчас.' FROM `quest_request_items` WHERE `ID`=7802 AND MD5(`CompletionText`)='9a08e9e815c17a62baefcaedf2ad0494' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=7802 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 8326, 'ruRU', 'Мне неприятно просить тебя уничтожать этих зверей. Хотя, в прошлые времена, мы жили в относительной гармонии с лесными существами, сейчас настали другие времена. Первым делом для всех Син\'дорай является выживание, постарайся запонить это.' FROM `quest_request_items` WHERE `ID`=8326 AND MD5(`CompletionText`)='8e96d8689714480ee86449efe02bb7cc' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=8326 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 8330, 'ruRU', 'Получилось ли у тебя найти мои вещи? Как только мы восстановим свое господство над Островом Солнечного Скитальца, они понадобятся мне в моей работе. Хотя сейчас я должен следить за Солнечным Колодцем... или над тем, что от него осталось.' FROM `quest_request_items` WHERE `ID`=8330 AND MD5(`CompletionText`)='74e3f93aa4b04cba2fc3ee78e28ef9c0' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=8330 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 8335, 'ruRU', 'Выслушай внимательно моё предостережение - Фелендрен Изгой является лишь симптомом гораздо более серьезной проблемы. Его смерть решит наши насущные проблемы, но всех кровавых эльфов постигнет та же судьба, что и его, если мы позволим нашим пристрастиям одержать верх над нами.' FROM `quest_request_items` WHERE `ID`=8335 AND MD5(`CompletionText`)='f151acb28f54ec8b46e9a41be01c0ee7' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=8335 AND x.`locale`='ruRU');
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) SELECT 8336, 'ruRU', 'Раньше большинство существ на острове были умиротворены и неагрессивны благодаря нашей магии.  Когда Плеть уничтожила Солнечный Колодец, мы утратили контроль над этими созданиями.  Магические осколки - это остатки того контроля, который у нас когда-то был, и поэтому они могут быть использованы для создания нового устройства, способного исправить ситуацию .$B$BЕще лучше, если с их помощью мы сможем узнать, что же на самом деле отравляет наш остров...' FROM `quest_request_items` WHERE `ID`=8336 AND MD5(`CompletionText`)='f69125726d99cde45e85edd5c8f3ef52' AND NOT EXISTS (SELECT 1 FROM `quest_request_items_locale` x WHERE x.`ID`=8336 AND x.`locale`='ruRU');
